124	export function calculateWeightedScore(results: PillarResult[], pageType: PageType): number {
125	  let totalWeight = 0;
126	  let weightedSum = 0;
127	  for (const r of results) {
128	    const w = getPillarWeight(r.pillar, pageType);
129	    weightedSum += r.score * w;
130	    totalWeight += w;
131	  }
132	  return totalWeight > 0 ? Math.round(weightedSum / totalWeight) : 0;
133	}
